import{_ as n,D as i,o as s,c as d,j as o,a as e,I as a,w as l,am as p}from"./chunks/framework.DXw8qDd0.js";const N=JSON.parse('{"title":"Codex 有效额度“翻倍”的小技巧","description":"","frontmatter":{"title":"Codex 有效额度“翻倍”的小技巧","time":"2026-06-07T00:00:00.000Z","tags":["codex"]},"headers":[],"relativePath":"笔记/Codex/Codex 有效额度“翻倍”的小技巧.md","filePath":"笔记/Codex/Codex 有效额度“翻倍”的小技巧.md"}'),_={name:"笔记/Codex/Codex 有效额度“翻倍”的小技巧.md"},r=p("<p>分享一个让Agent额度翻倍的小技巧。</p><p>之前发Codex教程的时候，评论区有一条留言被顶到了最高赞，是一个关于5小时额度窗口的小技巧。</p><p>然后发现很多朋友都说第一次知道，我觉得可以单独拿出来再给大家说一下。</p><p>先说原理。</p><p>不管是Codex还是Claude Code，它们的额度限制都不是每天重置或者每小时重置，而是一个5小时的滚动窗口。 也就是你发第一条消息的那一刻，5小时倒计时就开始了，这5个小时内你有一定的Token额度可以用，用完了，就得等这个窗口走完才能重置。</p><p>但这里有一个很多人不知道的细节。</p><p>5小时窗口结束之后，系统并不会自动帮你开启下一个窗口，它会一直等，等到你发出下一条消息的那一刻，才重新开始计算新的5小时。</p><p>比如你每天下午2点到6点是集中用Agent工作的时间。 如果你2点才开始用Codex，窗口就从2点开始算，到晚上7点才重置。中间如果用的比较猛，3点半额度就见底了，你得干等到7点，这基本就要当3个半小时的原始人了。</p><p>但如果你在上午11点的时候，提前给Codex发一条消息，哪怕就随便说一句话，窗口就从11点开始计算了，等于下午4点就重置了。 你2点开始干活，干到4点额度刷新了一波，4点以后，你又有一整个新窗口可以用。也就是说在2点到6点的核心工作时间里，你能享受的5小时额度窗口，直接从一个窗口变成了两个。</p><p>变相让你的额度变成了两倍。</p><p>原理就这么简单，提前触发窗口，让重置时间刚好落在你干活的中间。 很多人用了大半年agent，每次撞限了就硬等，因为可能确实不知道这个重置时间是可以自己控制的。</p><p>所以你只要理解了窗口的重置是可以人为控制的这一点，玩法就打开了，只要搭配上自动化，你就可以享受两倍额度窗口了。</p><p>说下怎么设置。 Codex比较简单，在左边菜单找到自动化，点进去以后新建一个，触发条件选「每天」，时间填你主要干活前的3小时，动作就是随便发一条短消息，内容无所谓，写个“叫我一声爹”都行。 设好之后就不用管了，每天到点它会自动跑一下，帮你把窗口提前激活。</p><p>Claude如果你有客户端，也是一样的，设置一个Routines自动化就行。 如果是CLI版，Mac就直接跟你的Agent说： “帮我设一个crontab定时任务，每天上午11点自动给Claude Code发一条消息“叫我一声爹”触发5小时窗口” Windows就用任务计划程序，也可以直接让Agent帮你配。</p><p>不过这里要提醒一下，5小时窗口是一层限制，但上面还有一个周额度的上限，所以不用贪心，让重置时间跟你的工作节奏对上就够了。</p><p>以上，希望对大家有用。</p>",16),c=o("p",null,"哇塞！现在不用等Codex的5h额度限制了！ 卡神教你钻空子哈哈哈🤫",-1),u=o("p",null,"Codex 额度是滚动 5 小时窗，下一窗要你主动发消息才开。 卡兹克玩法：设自动化，在开工前 3 小时发一句“叫老公”，让重置落进工作时段。",-1),h=o("p",null,"比如 你 14点开工 → 设上午11点， 这样下午16点 可以无缝衔接新的5h窗口。",-1),C=o("p",null,"我算了一下，我最近重度开发， 有时候1小时就打光额度，那我就得设定上午10点开启线程。",-1),x=o("p",null,[e("不过，周额度还在，还不能贪。哈哈哈"),o("br"),e(" 看还有啥无限续杯的经验交流？")],-1),m=p('<p>🚀分享一个让 Claude Code / Codex 有效额度“翻倍”的小技巧（很多重度用户用了大半年才知道）</p><p>之前 Codex 教程评论区被顶到最高赞的那条，就是这个 5 小时滚动窗口的玩法</p><p>今天系统性整理一下，帮大家少走弯路</p><p>核心原理（社区多次验证有效） Claude Code 和 Codex 的主要额度限制不是按自然天或小时固定重置，而是 5 小时滚动窗口（rolling 5-hour window）：</p><ul><li>从你发送第一条消息的那一刻，5 小时倒计时开始。</li><li>窗口结束后，不会立刻自动开启新窗口，而是等到你下一次发消息时，才启动新的 5 小时窗口。</li><li>上面还有一层周额度上限（weekly quota），重度用户容易撞到。</li></ul><p>关键：你完全可以人为控制窗口的启动时间</p><p>实际效果举例 假设你下午 2 点～6 点是集中 coding 时间：</p><ul><li>普通玩法：2 点第一次发消息 → 窗口到晚上 7 点结束。如果你 3 点半就把额度用完，就得干等到 7 点（浪费 3+ 小时）</li><li>优化玩法：上午 11 点提前发一条任意短消息（dummy prompt）→ 窗口从 11 点开始，到下午 4 点结束 <ul><li>2 点干活用到 4 点 → 额度刷新</li><li>4 点后再继续 → 又是一个全新 5 小时窗口</li></ul></li></ul><p>结果：同一个工作时段，从“只能用 1 个窗口”变成“能用 2 个窗口”，有效可用额度直接翻倍</p><p>很多用户实测一天能多出 8～15 小时的有效使用时间</p><p>如何自动化设置（一次设置，永久生效）</p><p>Codex：</p><ol><li>左侧菜单 → Automations（自动化）</li><li>新建 → 触发条件选「每天」</li><li>时间设为你主要工作前 3～4 小时（推荐早上 8～9 点）</li><li>动作：发送一条短消息（内容随便，比如“早上好”或“ping”）</li><li>保存即可，每天自动触发。</li></ol><p>Claude Code：</p><ul><li>客户端版：用 Routines / Automations 设置类似定时任务。</li><li>CLI 版（Mac,Linux）：让 Claude 帮你写 crontab：<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"></span></code></pre></div></li></ul>',15),g={id:"—-omega-欧米茄-ai-piercezhang34-·-2026-06-03-20-45",tabindex:"-1"},f=o("a",{class:"header-anchor",href:"#—-omega-欧米茄-ai-piercezhang34-·-2026-06-03-20-45","aria-label":'Permalink to "— [omega.欧米茄.AI (@PierceZhang34)](https://x.com/PierceZhang34/status/2062153817463156860) · 2026-06-03 20:45"'},"​",-1);function b(P,T,k,A,I,v){const t=i("VPNolebaseInlineLinkPreview");return s(),d("div",null,[r,o("p",null,[e("— "),a(t,{href:"https://x.com/Khazix0918/status/2062103999839707188",target:"_blank",rel:"noreferrer"},{default:l(()=>[e("数字生命卡兹克 (@Khazix0918)")]),_:1}),e(" · 2026-06-03 17:28")]),c,u,h,C,x,o("p",null,[e("— "),a(t,{href:"https://x.com/leaf_sanren/status/2062191492563902923",target:"_blank",rel:"noreferrer"},{default:l(()=>[e("Leaf Yeah! (@leaf_sanren)")]),_:1}),e(" · 2026-06-03 23:15")]),m,o("h2",g,[e("— "),a(t,{href:"https://x.com/PierceZhang34/status/2062153817463156860",target:"_blank",rel:"noreferrer"},{default:l(()=>[e("omega.欧米茄.AI (@PierceZhang34)")]),_:1}),e(" · 2026-06-03 20:45 "),f]),o("blockquote",null,[o("p",null,[e("📎 "),a(t,{href:"/ocdsync/笔记/"},{default:l(()=>[e("📒 返回笔记索引")]),_:1})])])])}const w=n(_,[["render",b]]);export{N as __pageData,w as default};
